style.css:
/* Make everything look chaotic and ugly */
* {
  font-family: "Comic Sans MS", "Papyrus", cursive; /* Use universally disliked fonts */
  color: #ff00ff; /* Bright pink text */
  background-color: #00ff00; /* Bright green background */
  text-transform: uppercase; /* Make all text uppercase */
  letter-spacing: 5px; /* Add excessive letter spacing */
  word-spacing: 10px; /* Add excessive word spacing */
  line-height: 1.2; /* Tight line spacing */
  border: 5px dashed #0000ff; /* Add a thick dashed border to everything */
  margin: 0 !important; /* Remove all nice spacing */
  padding: 0 !important; /* Remove all padding */
  box-shadow: 10px 10px 0px #ff0000; /* Add obnoxious shadows */
  transition: all 0.2s ease-in-out; /* Add random animations for extra chaos */
}

/* Make images look distorted */
img {
  filter: invert(100%) hue-rotate(180deg) blur(5px);
  transform: rotate(15deg) scale(1.2);
}

/* Destroy buttons */
button, a {
  background-color: #ff0000 !important; /* Bright red */
  color: #ffffff !important; /* White text */
  font-size: 24px !important; /* Oversized text */
  border: 5px solid #000000 !important; /* Thick black border */
  padding: 20px !important; /* Too much padding */
  transform: skew(10deg, 10deg); /* Skew the buttons */
  text-decoration: none !important; /* Remove default styles */
}

/* Randomize headers */
h1, h2, h3, h4, h5, h6 {
  text-align: center;
  text-shadow: 5px 5px #00ffff;
  background: linear-gradient(45deg, #ff0000, #00ff00, #0000ff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Make links painful to look at */
a {
  color: #ffff00 !important; /* Bright yellow text */
  background-color: #0000ff !important; /* Bright blue background */
  text-decoration: underline wavy red !important; /* Wavy underline */
}

/* Make tables unreadable */
table {
  border-collapse: collapse;
  width: 100%;
  background-color: #ff69b4; /* Hot pink */
}

td, th {
  border: 3px solid #000;
  padding: 10px;
  text-align: left;
}

/* Animations for chaos */
body {
  animation: rotateColors 3s infinite alternate;
}

@keyframes rotateColors {
  0% {
    filter: hue-rotate(0deg);
  }
  100% {
    filter: hue-rotate(360deg);
  }
}
